cypress_script:
describe('Date Picker Functionality', () => {
  it('should select a date successfully', () => {
    cy.visit('https://demoqa.com/date-picker');
    cy.get('#datePickerMonthYearInput').click();
    cy.get('.react-datepicker__day--021').click(); // Assuming this is the correct day in the date picker
    cy.get('#datePickerMonthYearInput').should('have.value', '07/21/2026');
  });

  it('should not change the URL when no date is selected', () => {
    cy.visit('https://demoqa.com/date-picker');
    cy.get('#datePickerMonthYearInput').click();
    cy.get('.react-datepicker__close-icon').click(); // Close without selecting a date
    cy.url().should('eq', 'https://demoqa.com/date-picker');
    cy.get('#datePickerMonthYearInput').should('have.value', '07/21/2026');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Date Picker Functionality', () => {
  test('should select a date successfully', async ({ page }) => {
    await page.goto('https://demoqa.com/date-picker');
    await page.click('#datePickerMonthYearInput');
    await page.click('.react-datepicker__day--021'); // Assuming this is the correct day in the date picker
    const value = await page.locator('#datePickerMonthYearInput').inputValue();
    expect(value).toBe('07/21/2026');
  });

  test('should not change the URL when no date is selected', async ({ page }) => {
    await page.goto('https://demoqa.com/date-picker');
    await page.click('#datePickerMonthYearInput');
    await page.click('.react-datepicker__close-icon'); // Close without selecting a date
    await expect(page).toHaveURL('https://demoqa.com/date-picker');
    const value = await page.locator('#datePickerMonthYearInput').inputValue();
    expect(value).toBe('07/21/2026');
  });
});
